import math
    import random
    import time

    LANGUAGE_WRAPPER = 'On a circular track of circumference {circumference}, there are {n_points} equally spaced marked points. They are labeled A_1, A_2, ..., A_{n_points} in some order, each label used exactly once. Bunbun starts at A_1, hops to A_2, then A_3, ..., then A_{n_points}, and finally back to A_1. Every hop is along the shorter arc between the two points (if the chord is a diameter, any semicircle may be used). Over all possible labelings, determine the maximal possible value of the sum of the {power}-th powers of the lengths of the {n_points} arcs that Bunbun traverses.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose n_points sufficiently large to avoid trivial cases and to ensure difficulty
# Ensure circumference is a multiple of n_points so arc lengths are integral multiples of a unit step
# Choose power >= 2 to make it strictly harder than the seed (which corresponds to power=1)
for _ in range(100):
    n = rng.randint(8, 2000)  # larger than seed's logic but still manageable
    t = rng.randint(1, 20)    # step size multiplier so circumference = n * t
    C = n * t
    p = rng.choice([2, 3, 4, 5])
    # Domain checks
    if n >= 8 and C > 0 and C % n == 0 and p >= 2:
        return {'n_points': n, 'circumference': C, 'power': p}
# Fallback deterministic assignment if random attempts somehow fail
n = 12
t = 3
C = n * t
p = 3
return {'n_points': n, 'circumference': C, 'power': p}

    def verifier(assign):
# Validate domain constraints and compute the maximal sum of power-th powers of arc lengths.
# The points are equally spaced: arc length unit = circumference / n_points.
# Each hop length is min(d, n - d) * unit, where d is the index-step between consecutive labels on the circle.
# We maximize sum of [min(d_i, n - d_i) * unit]^power over all permutations of labels.
# Known optimal structure:
# - For odd n: one can achieve all n hops of length floor(n/2) steps.
# - For even n: the optimal multiset of step-lengths is
#   { n/2 repeated n/2 times, (n/2 - 1) repeated (n/2 - 1) times, and 1 once }.
# This arrangement maximizes sums of any convex increasing function of the step-lengths, including x^power.
try:
    n = int(assign['n_points'])
    C = int(assign['circumference'])
    p = int(assign['power'])
except Exception:
    # Invalid assignment format
    return (False, None)
# Domain checks to enforce non-trivial hardness
if n < 8:
    # Too small; trivial or borderline cases
    return (False, None)
if C <= 0:
    return (False, None)
if C % n != 0:
    return (False, None)
if p < 2:
    # Must be strictly harder than the seed (seed corresponds to p = 1)
    return (False, None)
unit = C // n  # integer by construction
# Compute maximal sum of power-th powers of step-counts
if n % 2 == 1:
    k = (n - 1) // 2
    # All n arcs can be of length k steps
    S_steps = n * (k ** p)
else:
    half = n // 2
    # Optimal multiset counts: half of length half, (half - 1) of length (half - 1), and one of length 1
    S_steps = (half * (half ** p)) + ((half - 1) * ((half - 1) ** p)) + (1 ** p)
# Scale by unit^p to convert steps to actual arc lengths
answer = (unit ** p) * S_steps
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

